import {erasedROMSpans} from './rom-free-space.js';
import {crc32} from './zip.js';
const MAX=32*1024*1024,MAGIC=new TextEncoder().encode('PBCN-EDITOR-0001'),FOOT=40;
async function transform(bytes,kind,limit=128*1024*1024){if(kind!=='pack'&&typeof DecompressionStream==='undefined')throw Error('This device needs an updated browser or Android WebView to restore editable ROM data. You can still open the separate JSON project.');const Type=kind==='pack'?CompressionStream:DecompressionStream,stream=new Blob([bytes]).stream().pipeThrough(new Type('gzip')),reader=stream.getReader(),parts=[];let size=0;for(;;){const {done,value}=await reader.read();if(done)break;size+=value.length;if(size>limit){await reader.cancel();throw Error('Editable ROM metadata exceeds the safe size limit.');}parts.push(value);}return new Uint8Array(await new Blob(parts).arrayBuffer());}
export async function embedROMProject(compiled,source,project){
 if(typeof CompressionStream==='undefined')throw Error('This device cannot compress editable ROM data. Use ROM + editable project export.');
 const json=new TextEncoder().encode(JSON.stringify(project));if(json.length>64*1024*1024)throw Error('The editable project is too large to embed. Use ROM + editable project export.');
 const raw=new Uint8Array(8+source.length+json.length),v=new DataView(raw.buffer);v.setUint32(0,source.length,true);v.setUint32(4,json.length,true);raw.set(source,8);raw.set(json,8+source.length);const packed=await transform(raw,'pack');
 let end=compiled.length;while(end>0x200&&compiled[end-1]===255)end--;end=Math.min(compiled.length,(end+4099)&~3);
 const required=end+packed.length+FOOT;if(required>MAX)throw Error('This ROM has insufficient free space for its editable project. Save ROM + editable project instead; no editing data was discarded.');
 let size=compiled.length;while(size<required)size=Math.min(MAX,size*2);const bytes=new Uint8Array(size);bytes.fill(255);bytes.set(compiled);bytes.set(packed,end);const at=size-FOOT,f=new DataView(bytes.buffer,at,FOOT);bytes.set(MAGIC,at);f.setUint32(16,end,true);f.setUint32(20,packed.length,true);f.setUint32(24,crc32(packed),true);f.setUint32(28,crc32(compiled.subarray(0,end)),true);f.setUint32(32,raw.length,true);return bytes;
}
export async function embedROMOverlay(source,project){
 const raw=new TextEncoder().encode(JSON.stringify(project)),packed=await transform(raw,'pack'),bytes=source.slice(),spans=erasedROMSpans(source),chunks=[];
 if(source.subarray(source.length-FOOT).some(n=>n!==255))throw Error('The ROM footer is in use; save the project separately.');
 let consumed=0;for(const span of spans){if(consumed===packed.length)break;const count=Math.min(span.end-span.start-8,packed.length-consumed);if(count<1)continue;const view=new DataView(bytes.buffer,span.start,8);view.setUint32(4,count,true);bytes.set(packed.subarray(consumed,consumed+count),span.start+8);chunks.push({at:span.start,count});consumed+=count;}
 if(consumed!==packed.length)throw Error('Insufficient verified erased space for the editing snapshot.');
 chunks.forEach((c,i)=>new DataView(bytes.buffer,c.at,8).setUint32(0,chunks[i+1]?.at||0,true));const at=bytes.length-FOOT,f=new DataView(bytes.buffer,at,FOOT);bytes.set(MAGIC,at);f.setUint32(16,chunks[0].at,true);f.setUint32(20,packed.length,true);f.setUint32(24,crc32(packed),true);f.setUint32(28,crc32(source),true);f.setUint32(32,raw.length,true);f.setUint32(36,2,true);return bytes;
}
export async function recoverROMProject(bytes){
 if(bytes.length<FOOT)return null;const at=bytes.length-FOOT;if(!MAGIC.every((v,i)=>bytes[at+i]===v))return null;
 const f=new DataView(bytes.buffer,bytes.byteOffset+at,FOOT);if(f.getUint32(36,true)===2){const total=f.getUint32(20,true),parts=[],source=bytes.slice(),seen=new Set();let pos=f.getUint32(16,true),read=0;while(pos){if(pos<512||pos+8>=at||seen.has(pos))throw Error('Invalid editing snapshot chain.');seen.add(pos);const v=new DataView(bytes.buffer,bytes.byteOffset+pos,8),next=v.getUint32(0,true),size=v.getUint32(4,true);if(!size||pos+8+size>at||read+size>total)throw Error('Invalid editing snapshot chunk.');parts.push(bytes.slice(pos+8,pos+8+size));source.fill(255,pos,pos+8+size);read+=size;pos=next;}source.fill(255,at);if(read!==total||crc32(source)!==f.getUint32(28,true))throw Error('The playable ROM changed after its editing snapshot was saved.');const packed=new Uint8Array(await new Blob(parts).arrayBuffer());if(crc32(packed)!==f.getUint32(24,true))throw Error('The editing snapshot is damaged.');const raw=await transform(packed,'unpack');if(raw.length!==f.getUint32(32,true))throw Error('Invalid editing snapshot length.');return{source,project:JSON.parse(new TextDecoder().decode(raw))};}const end=f.getUint32(16,true),length=f.getUint32(20,true),rawLength=f.getUint32(32,true);if(end<0x200||end+length>at||rawLength>128*1024*1024)throw Error('Invalid editable ROM metadata bounds.');
 const packed=bytes.subarray(end,end+length);if(crc32(packed)!==f.getUint32(24,true))throw Error('The embedded project is damaged. Open a project backup.');if(crc32(bytes.subarray(0,end))!==f.getUint32(28,true))throw Error('This ROM was changed after its editor project was embedded. Its saved objects may no longer match. Import its native maps separately.');
 const raw=await transform(packed,'unpack');if(raw.length!==rawLength)throw Error('Invalid editable ROM metadata length.');const v=new DataView(raw.buffer),size=v.getUint32(0,true),jsonSize=v.getUint32(4,true);if(size<0x200||size>MAX||8+size+jsonSize!==raw.length)throw Error('Invalid embedded source/project lengths.');
 const project=JSON.parse(new TextDecoder().decode(raw.subarray(8+size)));return{source:raw.slice(8,8+size),project};
}

export async function romFingerprint(bytes){if(!globalThis.crypto?.subtle)throw Error('Secure file verification is unavailable. Use the ROM + project archive with its original source.');return [...new Uint8Array(await crypto.subtle.digest('SHA-256',bytes))].map(n=>n.toString(16).padStart(2,'0')).join('');}
export async function createROMRoundTrip(compiled,source,{sourceId=null,reports=[],previous=null}={}){
 const sourceFingerprint=await romFingerprint(source),compiledFingerprint=await romFingerprint(compiled),reuse=previous?.version===1&&previous.sourceFingerprint===sourceFingerprint&&previous.sourceLength===source.length;
 const sourceGzip=reuse?previous.sourceGzip:base64(await transform(source,'pack',MAX+1048576));
 const fingerprints=[...new Set([compiledFingerprint,...(reuse?[previous.compiledFingerprint,...previous.compiledFingerprints||[]]:[])])].filter(s=>/^[a-f0-9]{64}$/.test(s)).slice(0,12);
 return{version:1,compiledFingerprint,compiledFingerprints:fingerprints,sourceFingerprint,sourceId:sourceId||sourceFingerprint,sourceLength:source.length,sourceGzip,mapBindings:reports.map(r=>({mapId:r.mapId,key:r.key}))};
}
export async function resolveROMExportSource(project,bytes){
 const record=project?.romRoundTrip;if(record?.version!==1)return null;
 const sourceIds=new Set((project.maps||[]).map(m=>m.rom?.sourceId).filter(Boolean));if(!sourceIds.has(record.sourceId))return null;
 const hash=await romFingerprint(bytes);if(hash===record.sourceFingerprint)return null;
 if(![record.compiledFingerprint,...record.compiledFingerprints||[]].includes(hash))return null;
 const restored=await restoreROMProjectSidecar(project,bytes);return{source:restored.source,sourceId:restored.sourceId,compiledFingerprint:hash};
}
function base64(bytes){let text='';for(let at=0;at<bytes.length;at+=32768)text+=String.fromCharCode(...bytes.subarray(at,at+32768));return btoa(text);}
function unbase64(text){if(typeof text!=='string'||text.length>48*1024*1024||!/^[A-Za-z0-9+/=]*$/.test(text))throw Error('Invalid sidecar source data.');return Uint8Array.from(atob(text),c=>c.charCodeAt(0));}
export async function createROMProjectSidecar(compiled,source,project,options={}){const record=await createROMRoundTrip(compiled,source,{previous:project.romRoundTrip,...options}),copy=structuredClone(project);copy.romRoundTrip=record;if(new TextEncoder().encode(JSON.stringify(copy)).length>90*1024*1024)throw Error('This sidecar exceeds the project limit. Save the ROM + project archive with its separate original source.');return copy;}
export async function restoreROMProjectSidecar(project,compiled=null){const r=project?.romRoundTrip;if(r?.version!==1||!Number.isInteger(r.sourceLength)||r.sourceLength<512||r.sourceLength>MAX||!/^[a-f0-9]{64}$/.test(r.compiledFingerprint)||!/^[a-f0-9]{64}$/.test(r.sourceFingerprint)||typeof r.sourceId!=='string')throw Error('Choose a matching ROM project sidecar.');if(compiled){const hash=await romFingerprint(compiled);if(![r.compiledFingerprint,...r.compiledFingerprints||[],r.sourceFingerprint].includes(hash))throw Error('This sidecar does not match the opened playable or original source ROM. No project was replaced.');}const source=await transform(unbase64(r.sourceGzip),'unpack',MAX);if(source.length!==r.sourceLength||await romFingerprint(source)!==r.sourceFingerprint)throw Error('The sidecar source snapshot is damaged.');return{source,sourceId:r.sourceId,project:structuredClone(project)};}
